"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50638"],{94507(e){e.exports=JSON.parse('{"id":"FIN-120","slug":"going-concern","term":"Going Concern","also_known_as":[],"difficulty":"Beginner","definition":"Going concern is the assumption that a business will continue operating for the foreseeable future, usually at least twelve months, rather than closing down or being forced to sell its assets.","explanation":["Financial statements are normally prepared on the basis that the business will keep running. This affects how assets are valued. Equipment, for example, is shown at its cost less depreciation, reflecting its use over future years, rather than at the much lower price it might fetch in a quick sale.","Managers must assess whether this assumption is reasonable, and auditors check their judgment. Warning signs include repeated losses, running out of cash, being unable to repay debts as they fall due or losing a major customer.","If there is serious doubt about whether a business can continue, this must be disclosed in the financial statements, and the auditor may highlight it in their report. If the business is clearly going to close, the statements may need to be prepared on a different basis, valuing assets at what they would raise if sold.","A going concern warning is a significant red flag for investors and lenders, as it signals real risk that the company may fail."],"note":"","total":1500,"prev":{"slug":"goal-seek","term":"Goal Seek"},"next":{"slug":"going-concern-value","term":"Going-Concern Value"}}')}}]);